style.css:
@-moz-document url-prefix("https://www.google.") {
/* Fond global */
  html, body {
    background-color: #0b0b0b !important;
    color: #e0e0e0 !important;
  }

  /* Logo clair */
  img[alt="Google"] {
    filter: brightness(0) invert(1) !important;
  }

  /* Conteneur principal de la barre de recherche (input + icônes) — rendu très foncé */
  form[role="search"] .RNNXgb,
  form[role="search"] .a4bIc,
  .RNNXgb, .a4bIc {
    background-color: #000000 !important;
    border: 1px solid #111111 !important;
    border-radius: 28px !important;
    color: #e0e0e0 !important;
  }

  /* Assure que la zone interne hérite bien du conteneur (évite bandes plus claires sur les côtés) */
  form[role="search"] .RNNXgb > div,
  form[role="search"] .a4bIc > div {
    background: transparent !important;
  }

  /* Champ de saisie — transparent pour hériter du conteneur */
  input[name="q"], textarea[name="q"], input.gLFyf {
    background: transparent !important;
    border: none !important;
    color: #e0e0e0 !important;
    padding: 10px 20px !important;
    outline: none !important;
  }

  /* Placeholder plus discret */
  input[name="q"]::placeholder,
  input[name="q"]::-webkit-input-placeholder,
  input[name="q"]::-moz-placeholder,
  input[name="q"]:-ms-input-placeholder {
    color: #6b6b6b !important;
  }

  /* Empêche les wrappers d'icônes d'avoir un fond plus clair */
  .iblpc, .goxjub, .XDyW0e, .sbl1 { background: transparent !important; }

  /* Icônes (micro / lens / loupe) */
  svg, .XDyW0e {
    fill: #9aa0a6 !important;
    color: #9aa0a6 !important;
    opacity: 0.95 !important;
  }
  svg:hover, .XDyW0e:hover {
    fill: #fff !important;
    color: #fff !important;
  }

  /* Boutons (Recherche / J'ai de la chance) */
  .FPdoLc .gNO89b, .FPdoLc .RNmpXc,
  input[type="submit"], button[role="button"] {
    background-color: #0f0f0f !important;
    color: #e0e0e0 !important;
    border: 1px solid #222 !important;
    border-radius: 20px !important;
    padding: 8px 16px !important;
  }

  /* Pied de page / liens */
  #fbar, .fbar { background: transparent !important; color: #7a7a7a !important; }
  a { color: #9ab !important; }
  a:hover { color: #bcd !important; }
}
